const PREFIX = 'cerberus-shell-';
const CACHE = PREFIX + BUILD;

// Path prefixes that are never cached or answered by the worker.
const NEVER = ['/api/', '/v1/', '/preview/'];
// Exact paths that are never cached or answered by the worker.
const NEVER_EXACT = ['/api', '/v1', '/preview', '/healthz', '/sw.js'];
// Navigations the cached shell can stand in for.
const NAV = ['/', '/login'];

const shellSet = new Set(SHELL);

// route decides how a request is handled: "pass", "navigate" or "shell".
// req needs method, url, mode and headers.get().
function route(req, origin) {
  if (!req || req.method !== 'GET') return 'pass';
  let u;
  try { u = new URL(req.url); } catch { return 'pass'; }
  if (u.origin !== origin) return 'pass';
  const p = u.pathname;
  if (NEVER_EXACT.includes(p) || NEVER.some((pre) => p.startsWith(pre))) return 'pass';
  const accept = (req.headers && req.headers.get && req.headers.get('Accept')) || '';
  if (accept.includes('text/event-stream')) return 'pass';
  if (req.mode === 'navigate') return NAV.includes(p) && !u.search ? 'navigate' : 'pass';
  if (u.search) return 'pass';
  return shellSet.has(p) ? 'shell' : 'pass';
}

// A redirected response cannot answer a navigation; keep only its body.
async function clean(res) {
  if (!res.redirected) return res;
  const body = await res.blob();
  return new Response(body, { status: res.status, statusText: res.statusText, headers: res.headers });
}

async function precache() {
  const cache = await caches.open(CACHE);
  await Promise.all(SHELL.map(async (path) => {
    const res = await fetch(new Request(path, { cache: 'no-cache', credentials: 'same-origin' }));
    if (!res.ok) throw new Error(`precache ${path}: ${res.status}`);
    await cache.put(path, await clean(res));
  }));
}

async function shellResponse(req) {
  const cache = await caches.open(CACHE);
  const hit = await cache.match(req);
  return hit || fetch(req);
}

async function navigateResponse(req) {
  const cache = await caches.open(CACHE);
  let res;
  try {
    res = await fetch(req);
  } catch (err) {
    const hit = await cache.match('/');
    if (hit) return hit;
    throw err;
  }
  // A plain index.html (not a redirect or an error) from a newer build:
  // keep this worker's page, which matches the assets it serves.
  if (res.ok && !res.redirected && res.type !== 'opaqueredirect') {
    const hit = await cache.match('/');
    if (hit) {
      const [fresh, mine] = await Promise.all([res.clone().text(), hit.clone().text()]);
      if (fresh !== mine) return hit;
    }
  }
  return res;
}

self.addEventListener('install', (e) => {
  e.waitUntil(precache());
});

self.addEventListener('activate', (e) => {
  e.waitUntil((async () => {
    for (const name of await caches.keys()) {
      if (name.startsWith(PREFIX) && name !== CACHE) await caches.delete(name);
    }
    await self.clients.claim();
  })());
});

self.addEventListener('message', (e) => {
  if (e.data && e.data.type === 'skip-waiting') self.skipWaiting();
  if (e.data && e.data.type === 'build' && e.source) e.source.postMessage({ type: 'build', build: BUILD });
});

// A tap on a desktop notification (shown through the worker on phones):
// focus an open Cerberus tab and route it, or open one.
self.addEventListener('notificationclick', (e) => {
  e.notification.close();
  const raw = (e.notification.data && e.notification.data.link) || '';
  const link = /^#\/[^\s]*$/.test(raw) ? raw : '';
  e.waitUntil((async () => {
    const tabs = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
    for (const c of tabs) {
      if (new URL(c.url).origin !== self.location.origin) continue;
      await c.focus();
      if (link) c.postMessage({ type: 'route', link });
      return;
    }
    await self.clients.openWindow('/' + link);
  })());
});

self.addEventListener('fetch', (e) => {
  const kind = route(e.request, self.location.origin);
  if (kind === 'navigate') e.respondWith(navigateResponse(e.request));
  else if (kind === 'shell') e.respondWith(shellResponse(e.request));
  // "pass": no respondWith, the browser fetches it as usual.
});

// For tests (web/test/pwa.test.mjs runs this file in a sandbox).
self.cerberusSW = { route, navigateResponse, BUILD, CACHE, SHELL, NEVER, NEVER_EXACT, NAV };
